import{_ as p,C as r,o as n,c as o,j as a,a as s,E as l,a6 as i}from"./chunks/framework.CnPv4DE1.js";const g=JSON.parse('{"title":"任何东西你都能在两周内学会","description":"","frontmatter":{"title":"任何东西你都能在两周内学会","originalTitle":"You can learn anything in 2 weeks","date":"2025-07-17","originalUrl":"https://thedankoe.com/letters/you-can-learn-anything-in-2-weeks/","minutes":8,"sourceHash":"1dc05a232dbce05f591f902676f1f5d0f6349997b1db0830a598e60ed8754fc2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-can-learn-anything-in-2-weeks/"}]]},"headers":[],"relativePath":"letters/you-can-learn-anything-in-2-weeks.md","filePath":"letters/you-can-learn-anything-in-2-weeks.md"}'),h={name:"letters/you-can-learn-anything-in-2-weeks.md"};function c(d,e,m,f,k,u){const t=r("ArticleMeta");return n(),o("div",null,[e[0]||(e[0]=a("h1",{id:"任何东西你都能在两周内学会",tabindex:"-1"},[s("任何东西你都能在两周内学会 "),a("a",{class:"header-anchor",href:"#任何东西你都能在两周内学会","aria-label":'Permalink to "任何东西你都能在两周内学会"'},"​")],-1)),l(t),e[1]||(e[1]=i('<p>任何东西你都能在两周内学会。</p><p>不,我不是说你能在任何技能或话题上成为大师。我是说你能获取实现某个具体目标所需的具体知识。如果这个说法没有让你对自己能在人生重大里程碑上加速多少感到极度兴奋——比如赚更多钱、掌握一项有价值的技能,或者学一门语言、一种乐器,或者像 After Effects 这样的软件——那你可能还没理解我在说什么。</p><p>问题在于,人们已经被训练成这样一种思维:成功来自于把脑袋埋进课本 12 个小时以上,只为了参加一场考试,而你获取的知识中有 95% 在考完之后就烟消云散了。而当涉及到获得<em>现实世界</em>的结果时,那些知识里适用的部分不到 1%。</p><p>换句话说,你花在学习上的大部分时间都被彻底浪费了。</p><p>学校训练你以极其缓慢的方式学习。如果学习能让你变得有用、得到你想要的东西,那么想象一下,如果你花时间去<em>学习如何学习</em>,你能做到什么程度。你将能在别人达成一个目标所需的时间里,达成 10 个目标。</p><p>在这篇信里,我想向你展示到底该如何快速学会任何东西。</p><h3 id="技能习得-技巧叠加" tabindex="-1">技能习得 = 技巧叠加 <a class="header-anchor" href="#技能习得-技巧叠加" aria-label="Permalink to &quot;技能习得 = 技巧叠加&quot;">​</a></h3><p>你能<em>做</em>的一切都是一项技能。</p><p>这难道没有让你大吃一惊吗?</p><p>这个事实把生活简化了不少。整个斯多葛哲学的核心——“控制你能控制的东西”——是打开幸福之门的少数几把万能钥匙之一。如果你无法控制某件事,你可以控制自己对它的反应。因此,这就是一项管理你生活中大部分痛苦的核心技能。如果你能控制某件事,那你就可以练习它,直到它变得如此自然,以至于你学会了优雅从容地穿透现实,就像一个吉他手,不需要费多大力气就能完美弹奏一段令人惊叹的复杂独奏。</p><p>话虽如此,大多数人试图把技能作为一个整体来习得。这是一项极其杂乱无序的任务。选择“学吉他”这件事本身并不清晰。我们说的可是 5 年密集学习和练习的量。有数以万计的书籍、视频、文章和人,都想告诉你学吉他的“正确方法”。但他们教不会你怎么弹吉他,他们只能教你他们自己是怎么弹的。</p><p>那么,我们该如何抄近路学习新技能?我们该如何穿透噪音,确保只学到必要的东西?<em>通过理解技能是由技巧组成的。</em></p><p>如果我想学弹吉他,我不会从“学习”开始。</p><p>我从“弹”开始。学吉他的全部目的就是弹一首歌。这就引出了第一步:选一首要弹的歌。<em>从目的开始</em>。但现在你陷入了困境,你不知道怎么弹第一个音符。这就引出了第二步:找一个能教你那个音符是什么、以及弹它需要的指法的资源。如果你把这个不断试错的过程重复一两天,你大概就能弹出那首歌了,即便弹的时候听起来很糟糕、错误一堆。</p><p>你练得越多,弹那首特定歌曲就弹得越好。</p><p>当你转向下一首歌时,你会意识到,你为那首特定歌曲学到的各种技巧——横按和弦、闷音等等——让你学得快多了。</p><p>对创作者(你们大多数人)来说,一个更具体的例子是 Photoshop。</p><p>大多数人会直接去看一个一小时的教程,把侧边栏里每一个他妈的工具都讲一遍,而<em>你</em>则从你想<em>做</em>的事情开始:创作一张图片。如果你并没有在积极朝着一个需要用到 Photoshop 的目标努力,你就没必要去学 Photoshop。你学技能是为了实用,不是为了娱乐,因为那样你根本学不到那项技能。如果你觉得无聊,去看本小说吧。</p><p>从那里出发,你去搜索一个具体的<em>技巧</em>,比如一系列去除一棵树背景的步骤。通过研究,你找到了三种不同的选取和蒙版对象的方法(树特别难选取,至少在 Photoshop 把去背景变成一键操作之前是这样)。你把它们都试一遍,发现有一种方法效果不错,于是把它固化为你工具箱里的一项工具。仅凭这一点,你就学到了在 Photoshop 中蒙版处理大多数东西的关键一环。随着这些技巧不断叠加,你不仅省下了大量学习用不上的废话的时间,而且能有效地创作出你想到的绝大多数东西。</p><h3 id="心智的渐进超负荷" tabindex="-1">心智的渐进超负荷 <a class="header-anchor" href="#心智的渐进超负荷" aria-label="Permalink to &quot;心智的渐进超负荷&quot;">​</a></h3><p>技能是一组通过重复形成的神经通路。</p><p>我们可以把一个技巧看作单一的一条神经通路。是技能这幅拼图中的一块碎片。当你收集到足够多的碎片,能看到 80% 的图像时,你就能推断出获得结果所需的大部分内容。如果你懂几个说西班牙语的技巧,你至少能拼出一句话来表达你的意思。你最后可能说的是“我能买水吗?”而不是“最近的买瓶装水的地方在哪里?”,但你依然能把意思表达清楚,完成你的目标。</p><p>让我们来看一个更难的例子:赚钱。</p><p>这是每个人都想做的事,但很少有人把它看作一项可以学习的技能,因为金钱(和其他能改变人生的技能,比如社交动力学一样)与我们的自我形象、情绪和生存深深纠缠在一起。很难把金钱视为你能直接控制的事情,因为我们背负着来自父母、老师和人生经历的条件反射,它们影响着我们的认知。我们无法控制自己对冲动的反应,于是就形成了一层面纱,把金钱伪装成不可控的东西。</p><p>如果你能剥去所有阻碍你行动的非理性思维障碍,真正开始<em>去做那件事</em>,你会意识到,赚更多钱的能力其实能学得相当快。不是那种一夜暴富的骗局式速成,而是类似学习投三分球的那种速成。一个新手可能凭运气有 5% 的命中概率,但一个职业选手几乎不费什么力气就有 99% 的命中概率。</p><p>你从目的开始:赚钱。为了做到这一点,你需要一个产品或服务,以及一个客户。你没有产品的点子,那就去查找一种寻找有盈利潜力点子的技巧,<a href="https://letters.thedankoe.com/p/mega-guide-how-to-create-your-first" target="_blank" rel="noreferrer">比如这篇创建你第一个产品的超级指南</a>。如果你继续让自己的心思保持克制,你就会开始动手做这个产品,而不是花上一个月去纠结这个点子到底好不好,因为点子只有在行动中才会变得清晰。你不知道怎么吸引顾客,那就去查一种技巧,你会发现几种主要选项,比如社交媒体内容、付费广告和直接外联。你选一个,试一试。虽然你可能做得不怎么好,但你很幸运,因为你完全可以继续不断叠加和测试各种技巧,而且如果你专注于此,你学到的每一个技巧都会提高你的赚钱潜力。</p><p>如果你想卧推 315 磅,你不会在从没举过一次重量的情况下就把这个重量加到杠铃上。你也不会没完没了地看视频,指望它们教给你超出入门基础之外的东西(那些基础你看个 3 分钟的视频就够了)。然后你他妈得去健身房,加上重量,吃力地把它举起来,然后几天后再来看看自己能不能举更多。</p><p>渐进超负荷。</p><h3 id="超快学习中缺失的那味料" tabindex="-1">超快学习中缺失的那味料 <a class="header-anchor" href="#超快学习中缺失的那味料" aria-label="Permalink to &quot;超快学习中缺失的那味料&quot;">​</a></h3><p>快速学习需要的是纯粹的专注。</p><p>我不认为当今世界有多少人体验过这种状态。</p><p><em>纯 粹 的 专 注。</em> 除此之外什么都没有。只有你和任务。没有思绪。没有分心。所谓分心,是指任何把你的一丝注意力从目标上拉走的人、地方或事物。“你”这个人字面上不复存在了。你与现实融为一体。输入和输出合而为一。每一片进入你大脑的信息,都会立刻转化为原材料,如同钥匙对锁一般,直接嵌入现实之中。</p><p>你懂得该如何学习。你已经接近触及这种美妙的纯粹专注状态了。有时它会自然发生。你进入一段高强度的时期,你的心智会收缩聚焦到一个清晰的目标上。模式识别能力全速运转。书籍、内容、音乐和对话都获得了一个全新的维度。现实成为灵感的来源——它本来就一直是,也将一直是——但你没有分心把你从这种与“存在本身”的连接中拉走。</p><p>大多数时候,这种状态根本不会发生。学习是一场无聊的苦熬。在这种情况下,你或许可以<a href="https://letters.thedankoe.com/p/prompt-deep-work-accelerator" target="_blank" rel="noreferrer">让 AI 教练带你进入一场深度工作会</a>。但我确实有一个工具,是我在自己内心充满不协调感时——在我厌倦了目前所处的位置,而对自己想去的地方又几乎清晰起来的时候——会拿出来用的。</p><p>这个工具,我称之为“战术性压力”。它是一种环境工程手段。</p><p>就我自己来说,我大约在两周内学会了 After Effects,因为我把 YouTube 视频的分镜脚本里塞满了我根本不知道怎么做的动画。我每周都得做视频。这是一个让我得以生存下去的习惯。如果我不发布视频,熵增就会释放出来,我整个工作系统都会开始崩解。这比学习一样东西、去阻止那种崩解发生的过程要痛苦得多。</p><p>战术性压力是指,你把自己置于一个高压情境中,给自己设下一个强硬的截止日期,来实现你一直想要达成的目标。辞掉工作,让自己的事业行得通。搬进一个你根本负担不起的公寓,以此推动自己去追求那个新的职业。跟你心仪的人打个“嗨”,这样你至少得开始某种混乱的对话。你要么想办法搞成,要么犹豫不决然后被现实碾碎。战术性压力如此有效,是因为大多数人往往会陷入<a href="https://letters.thedankoe.com/p/this-single-decision-will-determine" target="_blank" rel="noreferrer">闲置状态</a>。他们在跌到谷底之前就麻痹了自己,永远不让当下处境的痛苦超过他们想要抵达之处所需承受的痛苦。这时候,就是你该动用战术性压力的时刻。就在你察觉到当前处境的痛苦正在拖住你、让你不断重复同样的 6 个月直到余生的那一刻。</p><p>把自己置于一个几乎逼着你以人力所能达到的最快速度,去学会你需要学的东西的环境里,从而实现那个能把你推向人生下一阶段的目标。</p><p>朋友们,这就是学习之道。</p><p>—— Dan</p><hr><p><a href="/en/letters/you-can-learn-anything-in-2-weeks">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',42))])}const b=p(h,[["render",c]]);export{g as __pageData,b as default};
